import { Component, inject } from '@angular/core';

@Component({
  selector: 'app-save-button',
  template: `
    <button (click)="save()">Save draft</button>
    <span>{{ status }}</span>
  `,
})
export class SaveButton {
  private readonly drafts = inject(DraftApi);
  status = '';

  save(): void {
    this.status = 'Saving...'; // shows: the click schedules a pass
    this.drafts.save().then(() => {
      this.status = 'Saved'; // never shows: nothing schedules a pass
    });
  }
}

import { Component, inject, signal } from '@angular/core';

@Component({
  selector: 'app-save-button',
  template: `
    <button (click)="save()">Save draft</button>
    <span>{{ status() }}</span>
  `,
})
export class SaveButton {
  private readonly drafts = inject(DraftApi);
  readonly status = signal('');

  save(): void {
    this.status.set('Saving...');
    this.drafts.save().then(() => {
      this.status.set('Saved'); // marks SaveButton, schedules a pass
    });
  }
}

