import { ChangeDetectorRef, Component, inject } from '@angular/core';

@Component({
  selector: 'app-legacy-status',
  template: `<span>{{ status }}</span>`,
})
export class LegacyStatus {
  private readonly cdr = inject(ChangeDetectorRef);
  private readonly drafts = inject(DraftApi);
  status = 'Saving...';

  constructor() {
    this.drafts.save().then(() => {
      this.status = 'Saved';
      this.cdr.markForCheck(); // the notification the field can't send
    });
  }
}
